import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals.active

for row in range(4, 16):
    c_val = vws.cell(row=row, column=3).value

    try:
        x = float(c_val)
    except (TypeError, ValueError):
        x = None

    if x is None:
        result = 0
    elif 5 <= x <= 6:
        result = 5
    elif 3 <= x <= 4:
        result = 3.75
    elif 1 <= x <= 2:
        result = 1
    else:
        result = 0

    ws.cell(row=row, column=4).value = result
    print(row, c_val, result)

wb.save(OUT)
